#define glow 2.
#define waves true
struct info {
    float dist;
    vec3 color;
    vec3 blending;
};
info SDFCircle(vec2 p,float r,vec3 color) {
    return info(length(p)-r,color,color);
}
info SDFEllipse(vec2 p,vec3 s,vec3 color) {
    return info(length(p/s.xy)-s.z,color,color);
}
info SDFSquare(vec2 p,vec2 s,vec3 color) {
    vec2 q = abs(p) - s;
    return info(length(max(q,0.))+min(max(q.x,q.y),0.),color,color);
}
info SDFSquareR(vec2 p,vec2 s,float r,vec3 color) {
    info base = SDFSquare(p,s,color);
    return info(base.dist - r,color,color);
}
info SDFSegment(vec2 p,vec2 a,vec2 b,vec3 color )
{
    vec2 pa = p-a, ba = b-a;
    float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
    return info(length( pa - ba*h ),color,color);
}
info obj(info a,info b) {
    vec3 blend = (a.blending + b.blending) / 2.;
    if (a.dist > b.dist) {
        return info(b.dist,b.color,blend);
    } else {
        return info(a.dist,a.color,blend);
    }
}
info intersect(info a,info b) {
    vec3 blend = (a.blending + b.blending) / 2.;
    if (a.dist > b.dist) {
        return info(a.dist,a.color,blend);
    } else {
        return info(b.dist,b.color,blend);
    }
}
info onion(info a,float r) {
    return info(abs(a.dist)-r,a.color,a.blending);
}
info roundSDF(info a,float r) {
    return info(a.dist-r,a.color,a.blending);
}
info intersectU(info a,info b,vec3 color) {
    if (a.dist > b.dist) {return(info(a.dist,color,color));} else {return (info(b.dist,color,color));}
}
// transform
vec2 rotate(vec2 p,float angle) {
    return p * mat2(cos(angle),sin(angle),-sin(angle),cos(angle));
}
info map(vec2 p) {
    //body
    info cur = onion(SDFEllipse(rotate(p,-3.3),vec3(2,1,50),vec3(0,0.8,0.9)),2.);
    // 'F'
    cur = obj(cur,roundSDF(SDFSegment(p,vec2(-50,35),vec2(-50,-30),vec3(0,0.8,0.9)),5.));
    cur = obj(cur,roundSDF(SDFSegment(p,vec2(-50,0),vec2(-20,0),vec3(0,0.8,0.9)),5.));
    cur = obj(cur,roundSDF(SDFSegment(p,vec2(-50,35),vec2(-10,35),vec3(0,0.8,0.9)),5.));
    // 'M'
    cur = obj(cur,roundSDF(SDFSegment(p,vec2(0,-40),vec2(0,15),vec3(0,0.8,0.9)),5.));
    cur = obj(cur,roundSDF(SDFSegment(p,vec2(30,-15),vec2(0,15),vec3(0,0.8,0.9)),5.));
    cur = obj(cur,roundSDF(SDFSegment(p,vec2(60,15),vec2(30,-15),vec3(0,0.8,0.9)),5.));
    cur = obj(cur,roundSDF(SDFSegment(p,vec2(60,15),vec2(60,-40),vec3(0,0.8,0.9)),5.));

    return cur;
}
float frac(float val) {
    return val - floor(val);
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Time varying pixel color
    info hit = map(fragCoord-iResolution.xy/2.);
    vec3 col;
    if (waves) {
        col = hit.blending * (frac(hit.dist/(glow*4.) + iTime));
    } else {
        col = hit.blending * (1. - frac(hit.dist/glow));
    }
    if (hit.dist < 0.000001) {
        col = hit.color;
    } else if (hit.dist > glow-glow/3. && !waves) {
        col = vec3(0,0,0);
    }
    // Output to screen
    fragColor = vec4(col,1.0);
}
